#include "ProviderPolicyDialog.h"
#include "ContextNote.h"
#include "DownloadPolicyEditor.h"
#include "DialogDraftGuard.h"
#include "profile/ProviderPolicy.h"
#include <QCheckBox>
#include <QDialogButtonBox>
#include <QLabel>
#include <QPushButton>
#include <QVBoxLayout>
namespace mlash {
ProviderPolicyDialog::ProviderPolicyDialog(AppController* controller,const QString& id,const QJsonObject& provider,QWidget* parent):QDialog(parent) {
    setAttribute(Qt::WA_DeleteOnClose); setObjectName("providerPolicyDialog"); setWindowTitle("提供者维护 · "+provider.value("name").toString()); resize(490,440); const auto providerId=provider.value("id").toString(); const auto expected=provider.value("policy").toObject(); DownloadPolicy inherited; for (const auto& p:controller->profiles()) if (p.id==id) inherited=p.download;
    auto* layout=new QVBoxLayout(this); auto* inherit=new QCheckBox("继承订阅下载策略"); inherit->setObjectName("inheritProviderDownload"); inherit->setChecked(!expected.contains("download")); layout->addWidget(inherit); auto* download=new DownloadPolicyEditor(expected.contains("download")?DownloadPolicy::fromJson(expected.value("download").toObject()):inherited); download->setEnabled(!inherit->isChecked()); layout->addWidget(download); connect(inherit,&QCheckBox::toggled,download,[download](bool value) { download->setEnabled(!value); });
    auto* automatic=new QCheckBox("定时更新此提供者"); automatic->setObjectName("automaticProviderUpdate"); automatic->setChecked(expected.value("automatic").toBool()); layout->addWidget(automatic); auto* form=new QFormLayout; auto* hours=new QSpinBox; hours->setObjectName("providerUpdateHours"); hours->setRange(1,168); hours->setSuffix(" 小时"); hours->setValue(expected.value("hours").toInt(12)); hours->setEnabled(automatic->isChecked()); form->addRow("更新周期",hours); layout->addLayout(form); connect(automatic,&QCheckBox::toggled,hours,&QWidget::setEnabled);
    const auto stamp=[](const QJsonValue& value) { const auto time=QDateTime::fromString(value.toString(),Qt::ISODate); return time.isValid()?time.toLocalTime().toString("yyyy-MM-dd HH:mm:ss"):QString("—"); }; const auto attempt=provider.value("maintenance").toObject(); auto* status=new QLabel(QString("快照下载：%1\n最近尝试：%2\n下次计划：%3%4").arg(stamp(provider.value("updated_utc")),stamp(attempt.value("last_attempt")),stamp(provider.value("next_update")),attempt.value("failures").toInt()>0?QString("\n连续失败 %1 次；按退避时间重试").arg(attempt.value("failures").toInt()):QString())); status->setTextFormat(Qt::PlainText); status->setWordWrap(true); layout->addWidget(status); layout->addWidget(contextNote("更新后需手动应用。","更新仅生成候选，不自动切换运行版。经本地代理下载失败时不会回退到直连。计划由应用常驻部分执行，关闭主窗口仍有效。")); auto* hint=new QLabel(attempt.value("error").toString()); hint->setObjectName("providerPolicyHint"); hint->setTextFormat(Qt::PlainText); hint->setWordWrap(true); layout->addWidget(hint);
    auto* actions=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel); auto* save=actions->button(QDialogButtonBox::Save); save->setObjectName("saveProviderPolicy"); save->setText("保存策略"); actions->button(QDialogButtonBox::Cancel)->setText("取消"); auto* reset=actions->addButton("清除此项策略",QDialogButtonBox::ResetRole); reset->setObjectName("clearProviderPolicy"); layout->addWidget(actions); const auto pending=pending_; const auto draft=[inherit,download,automatic,hours] { QJsonObject config{{"automatic",automatic->isChecked()},{"hours",hours->value()}}; if (!inherit->isChecked()) config["download"]=download->policy().toJson(); return config; };
    const auto submit=[=](const QJsonObject& config) { const auto checked=validateProviderPolicies({{providerId,config}}); if (!checked.ok) { hint->setText(checked.error); return; } *pending=true; actions->setEnabled(false); inherit->setEnabled(false); download->setEnabled(false); automatic->setEnabled(false); hours->setEnabled(false); controller->updateProviderPolicy(id,providerId,config,expected); };
    connect(actions,&QDialogButtonBox::accepted,this,[=] { submit(draft()); }); connect(reset,&QPushButton::clicked,this,[=] { submit({}); }); connect(actions,&QDialogButtonBox::rejected,this,&QDialog::reject); connect(controller,&AppController::operationFinished,this,[=,this](bool ok,const QString& message) { if (!*pending) return; *pending=false; if (ok) { accept(); return; } hint->setText(message); actions->setEnabled(true); inherit->setEnabled(true); download->setEnabled(!inherit->isChecked()); automatic->setEnabled(true); hours->setEnabled(automatic->isChecked()); }); const auto baseline=draft(); const auto update=[=] { save->setEnabled(!*pending&&draft()!=baseline&&validateProviderPolicies({{providerId,draft()}}).ok&&!controller->state().busy); }; for (auto* field:findChildren<QLineEdit*>()) connect(field,&QLineEdit::textChanged,this,[update] { update(); }); for (auto* field:findChildren<QComboBox*>()) connect(field,&QComboBox::currentIndexChanged,this,[update] { update(); }); for (auto* field:findChildren<QSpinBox*>()) connect(field,&QSpinBox::valueChanged,this,[update] { update(); }); for (auto* field:{inherit,automatic}) connect(field,&QCheckBox::toggled,this,[update] { update(); }); connect(controller,&AppController::stateChanged,this,update); reset->setEnabled(!expected.isEmpty()); update(); DialogDraftGuard::protect(this,[=] { return draft()!=baseline; },[pending] { return *pending; });
}
void ProviderPolicyDialog::reject() { if (!*pending_) QDialog::reject(); }
}
